
CREATE TABLE customs_declarations(id uuid PRIMARY KEY,merchant_id uuid NOT NULL,shipment_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(merchant_id,id),UNIQUE(merchant_id,id,shipment_id),UNIQUE(merchant_id,shipment_id),FOREIGN KEY(merchant_id,shipment_id) REFERENCES shipments(merchant_id,id));
CREATE TABLE customs_versions(merchant_id uuid NOT NULL,declaration_id uuid NOT NULL,version integer NOT NULL,shipment_id uuid NOT NULL,revision integer NOT NULL,payload_ciphertext text NOT NULL,input_hash char(64) NOT NULL,declared_minor bigint NOT NULL CHECK(declared_minor BETWEEN 0 AND 999999999999),currency char(3) NOT NULL REFERENCES financial_currencies(code),exponent smallint NOT NULL CHECK(exponent BETWEEN 0 AND 3),actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(merchant_id,declaration_id,version),UNIQUE(merchant_id,declaration_id,version,shipment_id),UNIQUE(merchant_id,declaration_id,version,shipment_id,revision),FOREIGN KEY(merchant_id,declaration_id,shipment_id) REFERENCES customs_declarations(merchant_id,id,shipment_id),FOREIGN KEY(merchant_id,shipment_id,revision) REFERENCES shipment_revisions(merchant_id,shipment_id,revision));
ALTER TABLE customs_declarations ADD FOREIGN KEY(merchant_id,id,version,shipment_id) REFERENCES customs_versions(merchant_id,declaration_id,version,shipment_id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE customs_items(id uuid PRIMARY KEY,merchant_id uuid NOT NULL,declaration_id uuid NOT NULL,version integer NOT NULL,position integer NOT NULL CHECK(position BETWEEN 1 AND 100),quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 100000),unit_minor bigint NOT NULL CHECK(unit_minor BETWEEN 0 AND 999999999999),total_minor bigint NOT NULL CHECK(total_minor=quantity::bigint*unit_minor AND total_minor<=999999999999),currency char(3) NOT NULL,exponent smallint NOT NULL,payload_ciphertext text NOT NULL,UNIQUE(merchant_id,declaration_id,version,position),FOREIGN KEY(merchant_id,declaration_id,version) REFERENCES customs_versions(merchant_id,declaration_id,version));
CREATE TABLE customs_profiles(merchant_id uuid NOT NULL REFERENCES merchants(id),version integer NOT NULL CHECK(version>0),payload_ciphertext text NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(merchant_id,version));
CREATE TABLE customs_country_rules(country char(2) PRIMARY KEY,version integer NOT NULL CHECK(version>0),active_version integer,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customs_rule_versions(country char(2) NOT NULL REFERENCES customs_country_rules(country),version integer NOT NULL,payload_ciphertext text NOT NULL,actor_id uuid NOT NULL,session_id uuid NOT NULL,auth_version integer NOT NULL,key_hash char(64) NOT NULL,digest char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(actor_id,key_hash),PRIMARY KEY(country,version),FOREIGN KEY(actor_id,session_id) REFERENCES auth_sessions(user_id,id));
ALTER TABLE customs_country_rules ADD FOREIGN KEY(country,active_version) REFERENCES customs_rule_versions(country,version) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE customs_rule_reviews(country char(2) NOT NULL,version integer NOT NULL,actor_id uuid NOT NULL,session_id uuid NOT NULL,key_hash char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(actor_id,key_hash),PRIMARY KEY(country,version),FOREIGN KEY(country,version) REFERENCES customs_rule_versions(country,version),FOREIGN KEY(actor_id,session_id) REFERENCES auth_sessions(user_id,id));
CREATE TABLE customs_readiness(id uuid PRIMARY KEY,merchant_id uuid NOT NULL,shipment_id uuid NOT NULL,revision integer NOT NULL,report jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(merchant_id,shipment_id,revision) REFERENCES shipment_revisions(merchant_id,shipment_id,revision));
CREATE TABLE customs_reviews(id uuid PRIMARY KEY,merchant_id uuid NOT NULL,declaration_id uuid NOT NULL,version integer NOT NULL,actor_id uuid NOT NULL,session_id uuid NOT NULL,grant_id uuid NOT NULL REFERENCES platform_access_grants(id),note_ciphertext text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(merchant_id,declaration_id,version) REFERENCES customs_versions(merchant_id,declaration_id,version),FOREIGN KEY(actor_id,session_id) REFERENCES auth_sessions(user_id,id));
CREATE TABLE customs_commands(merchant_id uuid NOT NULL REFERENCES merchants(id),actor_id uuid NOT NULL REFERENCES users(id),operation text NOT NULL,key_hash char(64) NOT NULL,digest char(64) NOT NULL,result_ciphertext text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(merchant_id,actor_id,operation,key_hash));
CREATE TABLE customs_events(id uuid PRIMARY KEY,merchant_id uuid NOT NULL REFERENCES merchants(id),shipment_id uuid,actor_id uuid REFERENCES users(id),kind text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(merchant_id,shipment_id) REFERENCES shipments(merchant_id,id));
CREATE TABLE customs_document_counters(merchant_id uuid NOT NULL REFERENCES merchants(id),kind text NOT NULL CHECK(kind IN ('invoice','packing_list')),number bigint NOT NULL CHECK(number>0),PRIMARY KEY(merchant_id,kind));
CREATE TABLE customs_documents(id uuid PRIMARY KEY,merchant_id uuid NOT NULL,declaration_id uuid NOT NULL,version integer NOT NULL,shipment_id uuid NOT NULL,revision integer NOT NULL,kind text NOT NULL CHECK(kind IN ('invoice','packing_list')),locale text NOT NULL CHECK(locale IN ('en','ar')),number text NOT NULL,invoice_date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(merchant_id,id),UNIQUE(merchant_id,kind,number),UNIQUE(merchant_id,declaration_id,version,kind,locale),FOREIGN KEY(merchant_id,declaration_id,version,shipment_id,revision) REFERENCES customs_versions(merchant_id,declaration_id,version,shipment_id,revision));
CREATE TABLE customs_document_work(id uuid PRIMARY KEY,merchant_id uuid NOT NULL,document_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),auth_version integer NOT NULL,origin_token_id uuid,origin_session_id uuid,state text NOT NULL CHECK(state IN ('pending','processing','completed','blocked','failed')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),lease_token uuid,lease_until timestamptz,error_code text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(merchant_id,id),UNIQUE(document_id),FOREIGN KEY(merchant_id,document_id) REFERENCES customs_documents(merchant_id,id),CHECK((origin_token_id IS NULL)<>(origin_session_id IS NULL)));
CREATE TABLE customs_document_results(document_id uuid PRIMARY KEY,merchant_id uuid NOT NULL,object_key text NOT NULL UNIQUE,checksum char(64) NOT NULL,size_bytes integer NOT NULL CHECK(size_bytes BETWEEN 1 AND 5242880),state text NOT NULL CHECK(state IN ('ready','quarantined')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(merchant_id,document_id) REFERENCES customs_documents(merchant_id,id));
CREATE TABLE customs_document_revocations(document_id uuid PRIMARY KEY,merchant_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(merchant_id,document_id) REFERENCES customs_documents(merchant_id,id));
CREATE INDEX customs_history ON customs_versions(merchant_id,shipment_id,revision);
CREATE INDEX customs_work_recovery ON customs_document_work(state,lease_until);
CREATE OR REPLACE FUNCTION customs_items_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE expected bigint;actual numeric; BEGIN
 SELECT declared_minor INTO expected FROM customs_versions WHERE merchant_id=NEW.merchant_id AND declaration_id=NEW.declaration_id AND version=NEW.version;
 SELECT coalesce(sum(total_minor),0) INTO actual FROM customs_items WHERE merchant_id=NEW.merchant_id AND declaration_id=NEW.declaration_id AND version=NEW.version;
 IF (SELECT count(*) FROM customs_items WHERE merchant_id=NEW.merchant_id AND declaration_id=NEW.declaration_id AND version=NEW.version) NOT BETWEEN 1 AND 100 OR expected<>actual OR EXISTS(SELECT 1 FROM customs_items i JOIN customs_versions v ON v.merchant_id=i.merchant_id AND v.declaration_id=i.declaration_id AND v.version=i.version WHERE i.merchant_id=NEW.merchant_id AND i.declaration_id=NEW.declaration_id AND i.version=NEW.version AND (i.currency<>v.currency OR i.exponent<>v.exponent)) THEN RAISE EXCEPTION 'Customs totals/currency inconsistent' USING ERRCODE='23514';END IF;RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER customs_item_totals AFTER INSERT ON customs_versions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION customs_items_guard();
CREATE CONSTRAINT TRIGGER customs_item_totals AFTER INSERT ON customs_items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION customs_items_guard();
CREATE OR REPLACE FUNCTION customs_rule_review_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN IF EXISTS(SELECT 1 FROM customs_rule_versions WHERE country=NEW.country AND version=NEW.version AND actor_id=NEW.actor_id) THEN RAISE EXCEPTION 'Independent rule reviewer required' USING ERRCODE='23514'; END IF;RETURN NEW;END $$;
CREATE TRIGGER customs_rule_review_guard BEFORE INSERT ON customs_rule_reviews FOR EACH ROW EXECUTE FUNCTION customs_rule_review_guard();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['customs_versions','customs_items','customs_profiles','customs_rule_versions','customs_rule_reviews','customs_readiness','customs_reviews','customs_commands','customs_events','customs_documents','customs_document_results','customs_document_revocations'] LOOP EXECUTE format('CREATE TRIGGER customs_history_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION shipping_immutable()',t);END LOOP;END $$;
CREATE OR REPLACE FUNCTION customs_version_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN IF NEW.merchant_id<>OLD.merchant_id OR NEW.shipment_id<>OLD.shipment_id OR NEW.id<>OLD.id OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Customs identity/version immutable' USING ERRCODE='23514'; END IF;RETURN NEW;END $$;
CREATE TRIGGER customs_version_guard BEFORE UPDATE ON customs_declarations FOR EACH ROW EXECUTE FUNCTION customs_version_guard();
CREATE TRIGGER customs_declaration_delete BEFORE DELETE OR TRUNCATE ON customs_declarations FOR EACH STATEMENT EXECUTE FUNCTION shipping_immutable();
CREATE OR REPLACE FUNCTION customs_work_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN IF (NEW.id,NEW.merchant_id,NEW.document_id,NEW.actor_id,NEW.auth_version,NEW.origin_token_id,NEW.origin_session_id,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.merchant_id,OLD.document_id,OLD.actor_id,OLD.auth_version,OLD.origin_token_id,OLD.origin_session_id,OLD.created_at) OR (OLD.state IN ('completed','blocked','failed') AND NEW IS DISTINCT FROM OLD) THEN RAISE EXCEPTION 'Document work identity/history immutable' USING ERRCODE='23514'; END IF;RETURN NEW;END $$;
CREATE TRIGGER customs_work_guard BEFORE UPDATE ON customs_document_work FOR EACH ROW EXECUTE FUNCTION customs_work_guard();
CREATE TRIGGER customs_work_delete BEFORE DELETE OR TRUNCATE ON customs_document_work FOR EACH STATEMENT EXECUTE FUNCTION shipping_immutable();
